// src/App.js
import React from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';
import './styles.css';
import { profileData, skillsData, projectsData } from './portfolioData';

function App() {
  return (
    <div className="pb-5">
      <div className="container max-w-4xl">

        {/* Modern Hero Section */}
        <header className="hero-section text-center">
          <h1 className="hero-title mb-3">{profileData.name}</h1>
          <h2 className="hero-subtitle mb-4">{profileData.title}</h2>

          <div className="d-flex justify-content-center gap-3">
            <a href={`mailto:${profileData.email}`} className="social-link">Email</a>
            <a href={profileData.github} className="social-link" target="_blank" rel="noreferrer">GitHub</a>
            <a href={profileData.linkedin} className="social-link" target="_blank" rel="noreferrer">LinkedIn</a>
          </div>
        </header>

        {/* Technical Expertise Section */}
        <section className="mb-5 bg-white p-5 rounded-4 shadow-sm border" style={{ borderColor: '#e2e8f0' }}>
          <h3 className="section-title text-center mb-4 border-bottom pb-3">Technical Expertise</h3>
          <div className="row text-center">
            <div className="col-md-6 mb-4 mb-md-0">
              <h4 className="h6 fw-bold text-secondary text-uppercase tracking-wide mb-3">AI & Data Science</h4>
              <div>
                {skillsData.ai.map(skill => <span key={skill} className="tech-badge">{skill}</span>)}
              </div>
            </div>
            <div className="col-md-6">
              <h4 className="h6 fw-bold text-secondary text-uppercase tracking-wide mb-3">Software & Web</h4>
              <div>
                {skillsData.dev.map(skill => <span key={skill} className="tech-badge">{skill}</span>)}
              </div>
            </div>
          </div>
        </section>

        {/* Interactive Project Grid */}
        <section>
          <h3 className="section-title text-center mb-4">Featured Projects</h3>
          <div className="row g-4">
            {projectsData.map((project, index) => (
              <div className="col-md-4" key={index}>
                <div className="project-card">
                  <h4 className="project-title">{project.title}</h4>
                  <p className="text-muted small mb-4">{project.description}</p>
                  <div className="mt-auto">
                    {project.tech.map(t => <span key={t} className="tech-badge">{t}</span>)}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </section>

      </div>
    </div>
  );
}

export default App;
